final class Lazy<T> implements Supplier<T> {
    private final Supplier<T> factory;
    private volatile T value;
    Lazy(Supplier<T> f) { factory = f; }
    public T get() {
        T v = value;                        // volatile read (fast path)
        if (v == null) synchronized (this) { if (value == null) value = factory.get(); v = value; }
        return v;
    }
}

private final FutureTask<Connection> conn =
    new FutureTask<>(() -> Dialer.dial(endpoint));

Connection connection() throws Exception {
    conn.run();            // no-op once completed
    return conn.get();     // blocks until acquired; rethrows the cached failure
}
